class Solution {
    public int vowelStrings(String[] words,int left,int right){
        int answer=0;
        for(int i=left;i<=right;i++){
            String word=words[i];
            if("aeiou".indexOf(word.charAt(0))>=0&&"aeiou".indexOf(word.charAt(word.length()-1))>=0)answer++;
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun vowelStrings(words:Array<String>,left:Int,right:Int):Int{
        var answer=0;
        for(i in left..right){
            val word=words[i];
            if(word.first() in "aeiou"&&word.last() in "aeiou")answer++
        };
        return answer
    }
}

code.cpp:
class Solution {
    public:int vowelStrings(vector<string>& words,int left,int right){
        int answer=0;
        string vowels="aeiou";
        for(int i=left;i<=right;++i)if(vowels.find(words[i].front())!=string::npos&&vowels.find(words[i].back())!=string::npos)++answer;
        return answer;
    }
};
